    abline(h = 0, col = "grey", lty = 2)

    img_name <- paste0("MD Plot_", sanitise_basename(contrast_data[i]), ".png")
    img_addr <- paste0("mdplot_", sanitise_basename(contrast_data[i]), ".png")
    image_data <- rbind(image_data, c(img_name, img_addr))
    invisible(dev.off())
}
